text:
Items flagged for instructor-specific difficulty
Item × instructor deviations whose 95% interval excludes zero. Positive values mean the item was easier for that instructor’s students than expected.


Show code
item_flags &lt;- estimate_grouplevel(m1) |&gt;
  as_tibble() |&gt;
  filter(Group == "item:instructor") |&gt;
  mutate(
    instructor = str_extract(Level, "[^:]+$"),
    item = str_remove(Level, ":[^:]+$")
  ) |&gt;
  separate_wider_delim(item, delim = " | ", names = c("exam", "question_title"), too_many = "merge") |&gt;
  filter(CI_low &gt; 0 | CI_high &lt; 0) |&gt;
  select(exam, question_title, instructor, Coefficient, CI_low, CI_high) |&gt;
  arrange(exam, question_title)

item_flags |&gt; select(-question_title)


# A tibble: 0 × 5
# ℹ 5 variables: exam &lt;chr&gt;, instructor &lt;chr&gt;, Coefficient &lt;dbl&gt;, CI_low &lt;dbl&gt;,
#   CI_high &lt;dbl&gt;




Show code
item_instructor &lt;- estimate_grouplevel(m1) |&gt;
  as_tibble() |&gt;
  filter(Group == "item:instructor") |&gt;
  mutate(
    instructor = str_extract(Level, "[^:]+$"),
    rank = rank(Coefficient, ties.method = "first"),
    .by = NULL
  ) |&gt;
  mutate(rank = rank(Coefficient, ties.method = "first"), .by = instructor)

ggplot(item_instructor, aes(x = rank, y = Coefficient)) +
  geom_hline(yintercept = 0, linetype = "dashed", color = "grey50") +
  geom_linerange(
    aes(ymin = CI_low, ymax = CI_high),
    color = "grey70",
    linewidth = 0.3
  ) +
  geom_point(color = "#4C72B0", size = 0.8) +
  facet_wrap(~instructor) +
  labs(
    title = "Item × Instructor Deviations in Difficulty",
    subtitle = "Each point is one item for one instructor, with 95% interval",
    x = "Items (ranked within instructor)",
    y = "Deviation (logit; positive = easier)"
  ) +
  theme_minimal(base_size = 13) +
  theme(
    plot.title = element_text(face = "bold"),
    panel.grid.minor = element_blank(),
    axis.text.x = element_blank()
  )

Items shared across semesters
Drift can only be measured on items that appear in both semesters.


Show code
shared_items &lt;- clean |&gt;
  distinct(semester, exam, question_title) |&gt;
  count(exam, question_title) |&gt;
  filter(n == 2) |&gt;
  select(-n)

clean_shared &lt;- clean |&gt;
  semi_join(shared_items, by = c("exam", "question_title"))

shared_items |&gt; count(exam, name = "n_shared_items")


